class Fraccion:
    def __init__(self, numerador, denominador):
        self.numerador = numerador
        self.denominador = denominador

    def __add__(self, other):
        nuevo_num = self.numerador * other.denominador + other.numerador * self.denominador
        nuevo_den = self.denominador * other.denominador
        return Fraccion(nuevo_num, nuevo_den)

    def __str__(self):
        return f"{self.numerador}/{self.denominador}"

class Caja:
    def __init__(self):
        self.items = []

    def agregar(self, item):
        self.items.append(item)

    def __len__(self):
        return len(self.items)

    def __contains__(self, item):
        return item in self.items

    def __iter__(self):
        return iter(self.items)

class Matriz:
    def __init__(self, filas, columnas):
        self.filas = filas
        self.columnas = columnas
        self.datos = [[0] * columnas for _ in range(filas)]

    def __getitem__(self, fila):
        return self.datos[fila]

    def __setitem__(self, fila, valores):
        self.datos[fila] = valores

