import unittest

class ValidadorEmail:
    @staticmethod
    def es_valido(email):
        return "@" in email and "." in email

class TestValidadorEmail(unittest.TestCase):
    def test_email_valido(self):
        self.assertTrue(ValidadorEmail.es_valido("user@example.com"))

    def test_sin_arroba(self):
        self.assertFalse(ValidadorEmail.es_valido("userexample.com"))

    def test_sin_punto(self):
        self.assertFalse(ValidadorEmail.es_valido("user@examplecom"))

class TestCuentaBancaria(unittest.TestCase):
    def setUp(self):
        self.cuenta = CuentaBancaria("Juan", 1000)

    def test_depositar(self):
        self.cuenta.depositar(500)
        self.assertEqual(self.cuenta.saldo, 1500)

    def test_retirar_valido(self):
        resultado = self.cuenta.retirar(500)
        self.assertTrue(resultado)
        self.assertEqual(self.cuenta.saldo, 500)

    def test_retirar_insuficiente(self):
        resultado = self.cuenta.retirar(2000)
        self.assertFalse(resultado)

# Código con bugs:
def calcular_promedio(notas):
    total = 0
    for nota in notas:
        total += nota
    return total / len(notas)  # Bug: división por cero si lista vacía

# Solución:
def calcular_promedio(notas):
    if not notas:
        return 0
    total = sum(notas)
    return total / len(notas)
